composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
    ports:
      - "{{envRaw.MDB_MCP_HTTP_PORT}}:{{envRaw.MDB_MCP_HTTP_PORT}}"
    volumes:
      - /opt/appdata/mongodb-mcp/logs:/data/logs
    environment:
      MDB_MCP_CONNECTION_STRING: {{env.MDB_MCP_CONNECTION_STRING}}
      MDB_MCP_API_CLIENT_ID: {{env.MDB_MCP_API_CLIENT_ID}}
      MDB_MCP_API_CLIENT_SECRET: {{env.MDB_MCP_API_CLIENT_SECRET}}
      MDB_MCP_READ_ONLY: {{env.MDB_MCP_READ_ONLY}}
      MDB_MCP_LOG_PATH: /data/logs
      MDB_MCP_LOGGERS: stderr
    command: ["--transport", "http", "--httpHost=0.0.0.0", "--httpPort={{envRaw.MDB_MCP_HTTP_PORT}}"]
